package dao;import model.*;import java.sql.*;import java.time.*;import java.util.*;
public class PaymentDAO5 extends DAO5{public PaymentDAO5(Connection c){super(c);}public Payment5 pay(Order5 o,String method)throws Exception{if(!Set.of("THE","VI_DIEN_TU","THU_THAT_BAI").contains(method))throw new IllegalArgumentException("Phương thức không hợp lệ");Payment5 p=new Payment5();p.setSoTien(o.getTongTien());p.setPhuongThuc(method);p.setThoiDiem(LocalDateTime.now());p.setTrangThai("THU_THAT_BAI".equals(method)?"FAILED":"SUCCESS");p.setId(insert("INSERT INTO tblPayment5(SoTien,PhuongThuc,ThoiDiem,TrangThai,tblOrder5id) VALUES(?,?,?,?,?)",p.getSoTien(),p.getPhuongThuc(),p.getThoiDiem(),p.getTrangThai(),o.getId()));return p;}}
